One common way this occurs is through **XML External Entity (XXE) injection**. When an XML parser is configured to allow external DTDs (Document Type Definitions), an attacker can supply a malicious XML file that references files on the server's local file system.

```java
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.xml.sax.InputSource;
import java.io.StringReader;

public class VulnerableXxeExample {
    public static void main(String[] args) throws Exception {
        // Malicious XML payload attempting to read /etc/passwd
        String xmlInput = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
                          "<!DOCTYPE foo [<!ENTITY xxe SYSTEM \"file:///etc/passwd\">]>" +
                          "<root>&xxe;</root>";

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // This parser is vulnerable because it allows external entities and DTDs by default
        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parsing the input
        builder.parse(new InputSource(new StringReader(xmlInput)));
    }
}
***
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.xml.sax.InputSource;
import java.io.StringReader;

public class SecureXxeExample {
    public static void main(String[] args) throws Exception {
        // Malicious XML payload
        String xmlInput = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
                          "<!DOCTYPE foo [<!ENTITY xxe SYSTEM \"file:///etc/passwd\">]>" +
                          "<root>&xxe;</root>";

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // FIX: Explicitly disable DTDs and external entities to prevent XXE attacks
        String FEATURE = "http://apache.org/xml/features/disallow-doctype-decl";
        factory.setFeature(FEATURE, true);

        // Disable external general entities
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // Disable external parameter entities
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Ignore external DTDs
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        // Disable XInclude
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);

        DocumentBuilder builder = factory.newDocumentBuilder();

        // Parsing the input will now ignore or throw an error for the malicious entity
        builder.parse(new InputSource(new StringReader(xmlInput)));
    }
}
